/usr/bin/bash -lc "perl - <<'PL'
use strict;
use warnings;

sub open_fastq {
    my ("'$path) = @_;
    if ($path =~ /'"\\.gz"'$/) {
        open(my $fh, '"'-|', 'gzip', '-cd', "'$path) or die "open gzip $path: $!";
        return $fh;
    }
    open(my $fh, '"'<', "'$path) or die "open $path: $!";
    return $fh;
}
sub norm_id {
    my ($h) = @_;
    $h =~ s/''^'"\\@//;
    "'$h =~ s/'"\\s.*"'$//;
    $h =~ s{/[12]$}{};
    return $h;
}
sub each_fastq {
    my ($path, $cb) = @_;
    my $fh = open_fastq($path);
    my $n=0;
    while (defined(my $h=<$fh>)) {
        my $s=<$fh>; my $p=<$fh>; my $q=<$fh>;
        die "truncated FASTQ $path at record ".($n+1) unless defined $q;
        chomp($h,$s,$p,$q); $h =~ s/'"\\r"'$//; $s =~ s/'"\\r"'$//; $p =~ s/'"\\r"'$//; $q =~ s/'"\\r"'$//;
        die "bad header $path at record ".($n+1) unless $h =~ /''^'"\\@/;
        die \"bad plus line "'$path at record ".($n+1) unless $p =~ /''^'"\\+/;
        die \"sequence/quality length mismatch "'$path at record ".($n+1) unless length($s)==length($q);
        ++$n;
        $cb->(norm_id($h),$s,$q,$n);
    }
    close($fh) or die "close $path failed";
    return $n;
}
my (%fi,%ri);
my $nf = each_fastq('"'/workspace/input_forward.fastq.gz', sub { my("'$id,$s,$q)=@_; die "duplicate input forward $id" if exists $fi{$id}; $fi{$id}="$s'"\\0"'$q"; });
my $nr = each_fastq('"'/workspace/input_reverse.fastq.gz', sub { my("'$id,$s,$q)=@_; die "duplicate input reverse $id" if exists $ri{$id}; $ri{$id}="$s'"\\0"'$q"; });
die "input counts differ" unless $nf==$nr;
die "input mate ID sets differ" unless scalar(keys %fi)==scalar(keys %ri);
for my $id (keys %fi) { die "input reverse missing $id" unless exists $ri{$id}; }
my (@fo,@ro);
my $nfo=each_fastq('"'/workspace/final_answer/filtered_forward.fastqsanger.gz', sub { push @fo, [@_[0,1,2]]; });
my "'$nro=each_fastq('"'/workspace/final_answer/filtered_reverse.fastqsanger.gz', sub { push @ro, [@_[0,1,2]]; });
die \"retained mate counts differ\" unless "'$nfo==$nro;
my %seen;
for (my $i=0; $i<$nfo; ++$i) {
    my ($fid,$fs,$fq)=@{$fo[$i]}; my ($rid,$rs,$rq)=@{$ro[$i]};
    die "mate ID mismatch at record ".($i+1) unless $fid eq $rid;
    die "duplicate retained ID $fid" if $seen{$fid}++;
    die "retained ID absent from input $fid" unless exists $fi{$fid} && exists $ri{$fid};
    die "forward sequence/quality changed for $fid" unless $fi{$fid} eq "$fs'"\\0"'$fq";
    die "reverse sequence/quality changed for $rid" unless $ri{$rid} eq "$rs'"\\0"'$rq";
}
print "input_pairs=$nf'"\\n\";
print \"retained_pairs="'$nfo'"\\n\";
print \"removed_proper_pairs=\".("'$nf-$nfo)."'"\\n\";
printf \"retention_fraction=%.6f\\n\", "'$nfo/$nf;
print "fastq_structure=PASS'"\\nmate_synchronization=PASS\\nretained_sequence_quality_identity=PASS\\n\";
PL
gzip -t /workspace/final_answer/filtered_forward.fastqsanger.gz /workspace/final_answer/filtered_reverse.fastqsanger.gz
sha256sum /workspace/final_answer/filtered_forward.fastqsanger.gz /workspace/final_answer/filtered_reverse.fastqsanger.gz"

