use strict;
use warnings;
sub open_fastq { my("'$p)=@_; if($p=~/'"\\.gz"'$/){open(my $f,'"'-|','gzip','-cd',"'$p) or die $!; return $f;} open(my $f,'"'<',"'$p) or die $!; return $f; }
sub norm_id { my($h)=@_; $h=~s/''^'"\\@//; "'$h=~s/'"\\s.*"'$//; $h=~s{/[12]$}{}; return $h; }
sub each_fastq {
  my($p,$cb)=@_; my $f=open_fastq($p); my $n=0;
  while(defined(my $h=<$f>)){my $s=<$f>;my $pl=<$f>;my $q=<$f>;die "truncated $p record ".($n+1) unless defined $q;
    for($h,$s,$pl,$q){chomp; s/'"\\r"'$//;}
    die "bad header $p record ".($n+1) unless $h=~/''^'"\\@/; die \"bad plus "'$p record ".($n+1) unless $pl=~/''^'"\\+/; die \"length mismatch "'$p record ".($n+1) unless length($s)==length($q);
    ++$n; $cb->(norm_id($h),join("'"\\n\","'$h,$s,$pl,$q),$n);
  }
  close($f) or die "close failed $p"; return $n;
}
my(%fi,%ri);
my $nf=each_fastq('"'/workspace/input_forward.fastq.gz',sub{my("'$id,$rec)=@_;die "duplicate input forward $id" if exists $fi{$id};$fi{$id}=$rec;});
my $nr=each_fastq('"'/workspace/input_reverse.fastq.gz',sub{my("'$id,$rec)=@_;die "duplicate input reverse $id" if exists $ri{$id};$ri{$id}=$rec;});
die '"'input pair count mismatch' unless "'$nf==$nr; for my $id(keys %fi){die "input reverse missing $id" unless exists $ri{$id};}
my(@fo,@ro);
my $nfo=each_fastq('"'/workspace/final_answer/filtered_forward.fastqsanger.gz',sub{push @fo,[@_[0,1]];});
my "'$nro=each_fastq('"'/workspace/final_answer/filtered_reverse.fastqsanger.gz',sub{push @ro,[@_[0,1]];});
die 'retained pair count mismatch' unless "'$nfo==$nro; my %seen;
for(my $i=0;$i<$nfo;++$i){my($fid,$frec)=@{$fo[$i]};my($rid,$rrec)=@{$ro[$i]};die "mate ID mismatch at ".($i+1) unless $fid eq $rid;die "duplicate retained $fid" if $seen{$fid}++;die "forward record modified $fid" unless exists $fi{$fid} && $fi{$fid} eq $frec;die "reverse record modified $rid" unless exists $ri{$rid} && $ri{$rid} eq $rrec;}
print "input_pairs=$nf'"\\nretained_pairs="'$nfo'"\\nremoved_proper_pairs=\".("'$nf-$nfo)."'"\\n\";printf \"retention_fraction=%.6f\\n\","'$nfo/$nf;print "fastq_structure=PASS'"\\nmate_synchronization=PASS\\nretained_record_identity=PASS\\n\";
PL
gzip -t /workspace/final_answer/filtered_forward.fastqsanger.gz /workspace/final_answer/filtered_reverse.fastqsanger.gz
sha256sum /workspace/final_answer/filtered_forward.fastqsanger.gz /workspace/final_answer/filtered_reverse.fastqsanger.gz"

